document.querySelector('.section-tabs')?.addEventListener?.('keydown',event=>{const tabs=[...document.querySelectorAll('.section-tabs [role="tab"]')].filter(t=>!t.hidden),i=tabs.indexOf(document.activeElement);if(i<0)return;const next={ArrowRight:(i+1)%tabs.length,ArrowLeft:(i-1+tabs.length)%tabs.length,Home:0,End:tabs.length-1}[event.key];if(next==null)return;event.preventDefault();tabs[next].focus();showSection(tabs[next].dataset.section)});
