function showLoadError(){$('export').disabled=true;const k=$('kpis');k.removeAttribute?.('aria-busy');k.innerHTML='<div class="load-error" role="alert"><div><b>Sales data didn’t load.</b><span>Check the connection and try again. Nothing was changed.</span></div><button type="button" id="load-retry">Retry</button></div>';const retry=document.querySelector('#load-retry');if(retry)retry.onclick=()=>{retry.disabled=true;retry.textContent='Retrying…';initialLoad()}}
function initialLoad(){return loadSalesSnapshot(true).then(()=>{$('export').disabled=false;$('kpis').removeAttribute?.('aria-busy');document.documentElement?.classList?.add('sales-ready');showSection(activeSection||'overview')}).catch(showLoadError)}
initialLoad();
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{hideTooltip();document.querySelectorAll('[data-page]').forEach(n=>n.classList.toggle('active',n===b));$('sales').hidden=b.dataset.page!=='sales';$('upload').hidden=b.dataset.page!=='upload';$('comparison').hidden=b.dataset.page!=='comparison';if($('approvals'))$('approvals').hidden=b.dataset.page!=='approvals'});
$('export').onclick=async()=>{if(!D)return;const button=$('export');button.disabled=true;try{const create=window.createTableWorkbook||(await import('./comparison-xlsx.js?v=32')).tableWorkbook,cols=tableColumns(),c=context('portfolio'),data=view.map(a=>cols.map(([key])=>a[key]==null?null:key.startsWith('ach')||key.startsWith('share')?a[key]/100:a[key]));const bytes=create({title:'Nerhadou · Portfolio detail',subtitle:c.caption+' · Target: '+c.targetLabel+' · '+(Object.entries(selection).filter(([,v])=>v.size).map(([k,v])=>k+': '+[...v].join(', ')).join(' · ')||'Total company'),columns:cols.map(([key,label])=>({label,width:key==='product'?30:24,kind:key.startsWith('ach')||key.startsWith('share')?'percent':key==='product'?'text':'number'})),rows:data,notes:['Exported '+new Date().toISOString()+' · Revision '+D.revision,'Sales shares use total company sales for the selected period, before product, line, distributor and channel filters. Missing values stay blank. Targets follow the selected target basis.']}),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download='nerhadou-portfolio-'+D.year+'-'+states.portfolio.metric+'-'+periodMode+'-'+periodMonths().join('_')+'-'+targetBasis+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}finally{button.disabled=false}};


window.addEventListener?.('scroll',hideTooltip,{passive:true});window.addEventListener?.('resize',hideTooltip);

window.refreshSalesSnapshot=async()=>loadSalesSnapshot();

function missingMetric(panel,metric){return missingReportingMonths().length>0||panelRows(panel).some(r=>r[metric]==null)}
for(const [name,panel,id,original] of [['renderMonthly','monthly','trend',renderMonthly],['renderDistributor','distributors','distributors',renderDistributor],['renderGroups','lines','lines-chart',renderGroups]]){
const wrapped=function(){if(missingMetric(panel,states[panel].metric)){const ctx=document.querySelector?.('#'+panel+'-context');if(ctx)try{ctx.textContent=context(panel).caption}catch{}$(id).innerHTML='<p class="empty-chart">Missing '+states[panel].metric+' data in this selection. Complete it in Data management.</p>';return}return original()};
 if(name==='renderMonthly')renderMonthly=wrapped;else if(name==='renderDistributor')renderDistributor=wrapped;else renderGroups=wrapped;
}
const originalRankings=renderRankings;renderRankings=function(){for(const [panel,id] of [['leaders','leaders'],['achievements','achievements']]){if(missingMetric(panel,states[panel].metric))$(id).innerHTML='<p class="empty-chart">Missing '+states[panel].metric+' data in this selection.</p>';else comparisonChart(panel,id,'product')}};
const originalTimeline=renderTimeline;renderTimeline=function(){if(missingMetric('timeline','units')||missingMetric('timeline','value')){$('timeline').innerHTML='<p class="empty-chart">Both units and value are required for this timeline. Some selected records are incomplete.</p>';return}originalTimeline()};
const originalSummary=renderSummary;renderSummary=function(){originalSummary();const cards=$('kpis').querySelectorAll?.('.kpi');if(!cards)return;for(const [metric,indexes] of [['units',[0,3]],['value',[1]]])if(missingMetric('summary',metric))for(const i of indexes){cards[i].querySelector('strong').textContent='—';cards[i].querySelector('small').textContent='Missing '+metric+' in selected records'}};

// Read-only analysis integration; existing import and authorization paths stay authoritative.
window.actualDashboard={focusFilter:(key,value)=>focusFilter(key,value),read:()=>D?({snapshot:D,months:periodMonths(),selection:Object.fromEntries(Object.entries(selection).map(([k,v])=>[k,[...v]])),periodMode,targetBasis,section:activeSection}):null,
 target:(product,metric,chosen=periodMonths(),annual=targetBasis==='annual')=>targetFor(product,{...context('summary'),months:chosen,count:annual?12:chosen.length},metric),
 render,showSection,wire,monthlyChartHTML,monthlyData,monthlyMetric:()=>states.monthly.metric,chartWidth,plotSVG,monthStride,compact,axisFor,axisTicks,tickLabel,
 apply:async config=>{if(!config||typeof config!=='object')return;const y=Number(config.year);if(Number.isInteger(y)&&D?.availableYears.includes(y)&&D.year!==y){actualYearChoice=String(y);await loadSalesSnapshot(true)}
 for(const k of Object.keys(selection))selection[k]=new Set((Array.isArray(config.selection?.[k])?config.selection[k]:[]).filter(v=>filterOptions(k).includes(v)));
 periodMode=config.periodMode==='selected'?'selected':'ytd';targetBasis=config.targetBasis==='annual'?'annual':'period';
 const ms=(Array.isArray(config.months)?config.months:[]).filter(m=>Number.isInteger(m)&&m>=1&&m<=12);if(periodMode==='selected')selectedMonths=new Set(ms);else if(ms.length){const avail=filterOptions('months').filter(m=>m<=Math.max(...ms));if(avail.length)$('period').value=String(Math.max(...avail))}followLatestPeriod=false;render();
 const section=['overview','analysis','trends','breakdown','portfolio','movement','forecast'].includes(config.section)?config.section:'overview';showSection(section);}
};
